"""Generate docs/final_numbers_v11.md from committed v11 and v11b result files (no hand-entered numbers)."""
import json, subprocess
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
L = lambda p: json.loads((ROOT / p).read_text(encoding="utf-8"))
v11 = L("results/v11/tune_viscosity/summary.json")
nv, nd, cb, fp = (L(f"results/v11/nested/{k}") for k in ("visc_summary.json", "dens_summary.json", "combined.json", "dens_final_params.json"))
new = L("results/v5/BASE/delta_ml_density/readings.json")
old = json.loads(subprocess.check_output(["git", "show", "3d38c7e:results/v5/BASE/delta_ml_density/readings.json"], cwd=ROOT))
f = lambda x, n=4: f"{x:.{n}f}"
o = ["# v11 final numbers: tuning the pair models", "",
     "Generated by `scripts/v11/build_final_numbers_v11.py` from `results/v11/` (v5-settings density numbers read from commit 3d38c7e) and `results/v5/BASE/delta_ml_density/`. Protocols: `docs/v11_predeclaration.md`, `docs/v11b_predeclaration.md`.", "",
     "## A. v11 first attempt (viscosity, random search, reshuffled-partition check)", "",
     f"Best of 30 random configurations: mean gain {f(v11['mean_gain'])} ln, 95 % interval {f(v11['ci_lo'])} to {f(v11['ci_hi'])}; rule not met (`adopt` = {v11['adopt']}). That check reused the systems the winner was chosen on, so it is optimistic.", "",
     "## B. v11b nested tuning (outer GroupKFold(5), inner GroupKFold(3), Optuna TPE, 60 trials per outer fold)", "",
     "| model | systems | v5 macro MAE | tuned macro MAE | mean gain | 95 % interval | one-sided p | Holm p | threshold | adopted |", "|---|---|---|---|---|---|---|---|---|---|"]
for k, r, u in (("visc", nv, "ln"), ("dens", nd, "kg/m3")):
    o.append(f"| {k} ({u}) | {r['n_systems']} | {f(r['mae_v5'])} | {f(r['mae_tuned'])} | {f(r['mean_gain'])} | {f(r['ci95'][0])} to {f(r['ci95'][1])} | {f(r['p_one_sided'])} | {f(cb[k]['p_holm'])} | {r['threshold']} | {cb[k]['adopt']} |")
o += ["", "Viscosity temperature-bin margins (R-MLV-6 definition, ln), v5 settings against tuned:", "", "| bin | v5 | tuned |", "|---|---|---|"]
for b in nv["margins_v5"]:
    o.append(f"| {b} | {f(nv['margins_v5'][b])} | {f(nv['margins_tuned'][b])} |")
o += ["", f"Margin guard satisfied: {nv['margin_guard_ok']}. Viscosity is therefore not adopted although the gain and Holm p pass: the margin below 263 K rises. v5 viscosity settings stay.", "",
      f"Density dev ternary rows ({nd['dev_ternary_rows']}), MAE kg/m3: ideal {f(nd['dev_ternary_mae']['ideal'],3)}, v5 ML {f(nd['dev_ternary_mae']['v5'],3)}, tuned ML {f(nd['dev_ternary_mae']['tuned'],3)}.", "",
      "## C. Density adoption (final tuning on all dev systems)", "",
      f"Final configuration: loss {fp['lgb']['objective']}, {fp['lgb']['n_estimators']} trees, learning rate {fp['lgb']['learning_rate']}, {fp['lgb']['num_leaves']} leaves, min child {fp['lgb']['min_child_samples']}, weight exponent {fp['weight_exponent']}. Applied in `src/fuelblend/ml/density_pair.py`; `models/v5/ml_density_pair` and `results/v5/BASE/delta_ml_density/` regenerated. The locked systems were read a second time (R-MLD-2 had already read them in v5), so the locked numbers are a second look, not a fresh hold-out.", "",
      "| reading | quantity | v5 settings | tuned |", "|---|---|---|---|"]
rows = [("R-MLD-1 dev OOF", "ML MAE kg/m3 (per system)", ["R-MLD-1", "ml", "mae_b"]), ("R-MLD-1 dev OOF", "gain over ideal", ["R-MLD-1", "ml", "gain"]),
        ("R-MLD-2 locked (second look)", "ML MAE kg/m3", ["R-MLD-2", "ml", "mae_b"]), ("R-MLD-2 locked (second look)", "gain over ideal", ["R-MLD-2", "ml", "gain"]),
        ("R-MLD-3 ternaries+ (row level)", "ML MAE kg/m3", ["R-MLD-3", "all", "mae_ml"]), ("R-MLD-3 ternaries+ (per system)", "gain over ideal", ["R-MLD-3", "all", "macro", "gain"]),
        ("R-MLD-4", "dev OOF margin kg/m3", ["R-MLD-4", "ml", "dev_oof_margin_kg_m3"]), ("R-MLD-4", "locked margin kg/m3", ["R-MLD-4", "ml", "locked_margin_kg_m3"])]
def g(d, p):
    for k in p: d = d[k]
    return d
for a, b, p in rows:
    o.append(f"| {a} | {b} | {f(g(old, p))} | {f(g(new, p))} |")
o += ["", f"Gate flags (v5 settings then tuned): R-MLD-3 pass {old['R-MLD-3']['pass']} then {new['R-MLD-3']['pass']}; promotion offered by the script {old['adoption']['promotion_offered']} then {new['adoption']['promotion_offered']}.", "",
      "Reading: the tuned density pair model lowers lab error on dev and on the already-read locked systems. Row-level ternary error is about equal to the ideal-volume rule (dev ternary MAE above), so density stays a labelled variant and is not promoted to the designated route; that decision is the user's. No laboratory validation exists."]
(ROOT / "docs/final_numbers_v11.md").write_text("\n".join(o) + "\n", encoding="utf-8")
print("ok")
